# Usage

## Totals

```js
import { computeTotal } from '../src/checkout.js';

computeTotal([{ price: 10, qty: 2 }], { discountCode: 'SAVE10' });
```

## Shipping Cost

```js
import { shippingCost } from '../src/shipping.js';

// Free shipping for subtotal >= $120
shippingCost(150);
// => 0

// Flat rate of $3.99 for subtotal < $120
shippingCost(89.99);
// => 3.99
```

## Checkout Summary

```js
import { checkoutSummary } from '../src/summary.js';

// Basic checkout without discount code
checkoutSummary([
  { price: 25.00, qty: 2 },
  { price: 15.50, qty: 1 }
]);
// => {
//   subtotal: 65.50,
//   shipping: 3.99,
//   total: 65.50,
//   grandTotal: 69.49
// }

// Checkout with discount code (subtotal >= $120 for free shipping)
checkoutSummary([
  { price: 30.00, qty: 2 },
  { price: 35.00, qty: 2 }
], { discountCode: 'SAVE10' });
// => {
//   subtotal: 130.00,
//   shipping: 0,
//   total: 117.00,
//   grandTotal: 117.00
// }
```
